using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Adds a new notification sound to the list of saved notification sounds. The new notification sound is added to the top of the list. If it is already in the list, its position isn't changed
    /// </summary>
    public Task<TdLib.TdApi.Objects.NotificationSound> AddSavedNotificationSoundAsync(InputFile sound = default)
    {

           using var activity =  StartCallActivity("AddSavedNotificationSoundAsync", typeof(AddSavedNotificationSound).FullName ?? "AddSavedNotificationSoundAsync");

           try
           {
             return client.AddSavedNotificationSoundAsync(sound);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
